func (s *contentNodeShifter) assignLanguagePage(nodes contentNodeIs, n *pageState) contentNodeIs {
	if nodes == nil {
		nodes = s.newContentNodeSlots()
	} else if s.numLanguages > 0 && len(nodes) < s.numLanguages {
		grown := s.newContentNodeSlots()
		copy(grown, nodes)
		nodes = grown
	}
	idx := s.contentNodeLanguageIndex(n)
	if idx >= 0 && idx < len(nodes) {
		nodes[idx] = n
	}
	return nodes
}

func (s *contentNodeShifter) assignLanguageResource(nodes resourceSources, n *resourceSource) resourceSources {
	if nodes == nil {
		nodes = s.newResourceSlots()
	} else if s.numLanguages > 0 && len(nodes) < s.numLanguages {
		grown := s.newResourceSlots()
		copy(grown, nodes)
		nodes = grown
	}
	idx := s.contentNodeLanguageIndex(n)
	if idx >= 0 && idx < len(nodes) {
		nodes[idx] = n
	}
	return nodes
}

func (sh *contentNodeShifter) collectAndMarkStaleIdentities(p *paths.Path) []identity.Identity {
	t := sh.trees

	key := p.Base()
	var ids []identity.Identity
	// We need only one identity sample per dimension.
	nCount := 0
	cb := func(n contentNodeI) bool {
		if n == nil {
			return false
		}
		n.MarkStale()
		if nCount > 0 {
			return true
		}
		nCount++
		n.ForEeachIdentity(func(id identity.Identity) bool {
			ids = append(ids, id)
			return false
		})

		return false
	}
	tree := t.treePages
	nCount = 0
	tree.ForEeachInDimension(key, doctree.DimensionLanguage.Index(),
		cb,
	)

	tree = t.treeResources
	nCount = 0
	tree.ForEeachInDimension(key, doctree.DimensionLanguage.Index(),
		cb,
	)

	if p.Component() == files.ComponentFolderContent {
		// It may also be a bundled content resource.
		key := p.ForBundleType(paths.PathTypeContentResource).Base()
		tree = t.treeResources
		nCount = 0
		tree.ForEeachInDimension(key, doctree.DimensionLanguage.Index(),
			cb,
		)

	}
	return ids
}

